import * as assert from 'assert';

interface CreditEntry {
    id: string;
    amount: number;
}

interface CreditUsed {
    id: string;
    used: number;
}

interface Invoice {
    gross: number;
    net: number;
    creditsUsed: CreditUsed[];
}

class UsageBilling {
    ratePerUnit: number;
    minimumCommit: number;
    credits: CreditEntry[];
    invoices: Record<string, Invoice>;
    totalBilled: number;

    constructor(ratePerUnit: number, minimumCommit: number) {
        this.ratePerUnit = ratePerUnit;
        this.minimumCommit = minimumCommit;
        this.credits = [];
        this.invoices = {};
        this.totalBilled = 0;
    }

    addCredit(creditId: string, amount: number): void {
        this.credits.push({ id: creditId, amount });
    }

golden_completion:
closePeriod(periodId: string, units: number): Invoice {
    if (this.invoices[periodId]) {
        return this.invoices[periodId];
    }
    const gross = Math.max(units * this.ratePerUnit, this.minimumCommit);
    let remaining = gross;
    const creditsUsed: CreditUsed[] = [];
    while (remaining > 0 && this.credits.length > 0) {
        const credit = this.credits[0];
        const used = Math.min(credit.amount, remaining);
        creditsUsed.push({ id: credit.id, used });
        credit.amount -= used;
        remaining -= used;
        if (credit.amount <= 0) {
            this.credits.shift();
        }
    }
    const net = remaining;
    this.totalBilled += net;
    const invoice: Invoice = { gross, net, creditsUsed };
    this.invoices[periodId] = invoice;
    return invoice;
}

