    let grossTax = 0;
    let prev = 0;
    for (const bracket of this.brackets) {
        if (taxableIncome <= prev) break;
        const taxableInBracket = Math.min(taxableIncome, bracket.upTo) - prev;
        grossTax += taxableInBracket * bracket.rate;
        prev = bracket.upTo;
    }
    grossTax = Math.round(grossTax * 100) / 100;
    const appliedCredits = Math.min(credits, grossTax);
    const netTax = grossTax - appliedCredits;
    const refundOrOwed = withheld - netTax;
    const result: TaxResult = { grossTax, credits: appliedCredits, netTax, withheld, refundOrOwed };
    this.results.set(filingId, result);
    return result;
}

