        return { from: fromId, to: toId, gross: amount, fee: 0, net: 0, day, status: 'account_not_found' };
    }

    if (day !== from.lastTransferDay) {
        from.dailyTransferred = 0;
    }

    if (from.dailyTransferred + amount > this.dailyLimit) {
        return { from: fromId, to: toId, gross: amount, fee: 0, net: 0, day, status: 'daily_limit_exceeded' };
    }

    const fee = Math.max(amount * this.feeRate, this.minFee);
    const totalDebit = amount + fee;

    if (from.balance < totalDebit) {
        return { from: fromId, to: toId, gross: amount, fee, net: 0, day, status: 'insufficient_funds' };
    }

    from.balance -= totalDebit;
    to.balance += amount;
    from.dailyTransferred += amount;
    from.lastTransferDay = day;

    const audit: TransferAudit = {
        from: fromId,
        to: toId,
        gross: amount,
        fee,
        net: amount,
        day,
        status: 'success'
    };
    this.auditLog.push(audit);
    return audit;
}

