    const tierName = this.clientTiers.get(clientId);
    if (!tierName) return { allowed: false, reason: 'client_not_registered' };

    const tier = this.tiers.get(tierName)!;
    const logs = this.requestLogs.get(clientId) || [];

    const burstCount = logs.filter(log => log.allowed && log.timestamp >= timestamp - 5 && log.timestamp <= timestamp).length;
    const minuteCount = logs.filter(log => log.allowed && log.timestamp >= timestamp - 60 && log.timestamp <= timestamp).length;
    const hourCount = logs.filter(log => log.allowed && log.timestamp >= timestamp - 3600 && log.timestamp <= timestamp).length;

    if (burstCount >= tier.burstSize) {
        const burstLogs = logs.filter(log => log.allowed && log.timestamp >= timestamp - 5 && log.timestamp <= timestamp);
        const oldestBurst = burstLogs.sort((a, b) => a.timestamp - b.timestamp)[0];
        const retryAfter = oldestBurst ? oldestBurst.timestamp + 5 - timestamp : 0;

        logs.push({ timestamp, endpoint, allowed: false });
        this.requestLogs.set(clientId, logs);

        return { allowed: false, reason: 'burst_exceeded', retryAfter };
    }

