        const minuteLogs = logs.filter(log => log.allowed && log.timestamp >= timestamp - 60 && log.timestamp <= timestamp);
        const oldestMinute = minuteLogs.sort((a, b) => a.timestamp - b.timestamp)[0];
        const retryAfter = oldestMinute ? oldestMinute.timestamp + 60 - timestamp : 0;

        logs.push({ timestamp, endpoint, allowed: false });
        this.requestLogs.set(clientId, logs);

        return { allowed: false, reason: 'minute_exceeded', retryAfter };
    }

    if (hourCount >= tier.requestsPerHour) {
        const hourLogs = logs.filter(log => log.allowed && log.timestamp >= timestamp - 3600 && log.timestamp <= timestamp);
        const oldestHour = hourLogs.sort((a, b) => a.timestamp - b.timestamp)[0];
        const retryAfter = oldestHour ? oldestHour.timestamp + 3600 - timestamp : 0;

        logs.push({ timestamp, endpoint, allowed: false });
        this.requestLogs.set(clientId, logs);

        return { allowed: false, reason: 'hour_exceeded', retryAfter };
    }

    logs.push({ timestamp, endpoint, allowed: true });
    this.requestLogs.set(clientId, logs);

    return {
        allowed: true,
        remaining: {
            burst: tier.burstSize - burstCount - 1,
            minute: tier.requestsPerMinute - minuteCount - 1,
            hour: tier.requestsPerHour - hourCount - 1
        }
    };
