interface ExpRes { ready:boolean; winner:string|null; stats:Record<string,{n:number;conv:number;rate:number}> }
class ABTest {
    variants: string[];
    minN: number;
    obs: Obs[] = [];
    constructor(variants:string[], minN:number) { this.variants=variants; this.minN=minN; }
    record(o: Obs): boolean { if (!this.variants.includes(o.variant)) return false; this.obs.push(o); return true; }

golden_completion:
evaluate(): ExpRes {
    const stats: Record<string,{n:number;conv:number;rate:number}> = {};
    for (const v of this.variants) {
        const vo = this.obs.filter(o=>o.variant===v);
        const conv = vo.filter(o=>o.converted).length;
        stats[v] = { n:vo.length, conv, rate: vo.length>0 ? conv/vo.length : 0 };
    }
    if (this.variants.some(v=>stats[v].n<this.minN))
        return { ready:false, winner:null, stats };
    const [a,b] = this.variants;
    const pool = (stats[a].conv+stats[b].conv)/(stats[a].n+stats[b].n);
    const se = Math.sqrt(pool*(1-pool)*(1/stats[a].n+1/stats[b].n));
    if (se===0) return { ready:true, winner:null, stats };
    const z = Math.abs(stats[a].rate-stats[b].rate)/se;
    const sig = z > 1.96;
    return { ready:true, winner: sig?(stats[a].rate>stats[b].rate?a:b):null, stats };
}

