check(key: string, now: number): RLRes {
    const pen = this.pens.get(key);
    if (pen !== undefined && now < pen) {
        return { allowed: false, remaining: 0, retryMs: pen - now };
    }
    // clear penalty if expired
    if (pen !== undefined && now >= pen) {
        this.pens.delete(key);
    }

    let hits = this.hits.get(key);
    if (!hits) {
        hits = [];
        this.hits.set(key, hits);
    }
    // remove old hits
    hits = hits.filter(t => t > now - this.winMs);
    this.hits.set(key, hits);

    if (hits.length >= this.max) {
        this.pens.set(key, now + this.penMs);
        const v = this.viols.get(key) || 0;
        this.viols.set(key, v + 1);
        return { allowed: false, remaining: 0, retryMs: this.penMs };
    }

    hits.push(now);
    return { allowed: true, remaining: this.max - hits.length, retryMs: 0 };
}

